import {Game,BOARD,GROUPS,TOKENS,CARDS} from './engine.js';
import {BoardView,CanvasBoardView} from './board-view.js';
const $=id=>document.getElementById(id);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`֏${Math.round(n*1000).toLocaleString('en-US')}`;
const color=i=>BOARD[i].type==='property'?GROUPS[BOARD[i].group].color:BOARD[i].type==='station'?'#546e5a':'#a99764';
const key='yerevan-monopoly-v1';let game,view,started=false,saved=null,toastTimer,modalKind='',busy=false,tradeDraft=null;
const on=(id,fn)=>{if($(id))$(id).onclick=fn;};
try{saved=JSON.parse(localStorage.getItem(key));if(!saved||saved.version!==1||!Array.isArray(saved.players)||saved.players.length<2||saved.players.length>4)saved=null;}catch{}
game=new Game(['Player 1','Player 2']);
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4400);}
function save(){if(!started)return;try{localStorage.setItem(key,JSON.stringify(game.s));$('save-label').textContent='✓ Progress saved on this browser';}catch{$('save-label').textContent='Browser storage unavailable — export your save from the menu.';}}
function modal(html,kind='',wide=false,closable=true){modalKind=kind;$('overlay').hidden=false;$('modal').className=`modal${wide?' wide':''}`;$('modal').innerHTML=`${closable?'<button class="close" id="close-modal" aria-label="Close dialog">×</button>':''}${html}`;const h=$('modal').querySelector('h2');if(h)h.id='modal-title';on('close-modal',closeModal);requestAnimationFrame(()=>{$('modal').querySelector('button,input,select,summary')?.focus({preventScroll:true});});}
function closeModal(){if(['buy','card','auction','buildingClaims','debt','transfer','won'].includes(game.s.phase)&&started){showPhase();return;}$('overlay').hidden=true;modalKind='';}
function perform(fn,after){try{fn();save();render();if(after)after();else showPhase();}catch(e){toast(e.message);}}
function actor(){return game.s.phase==='debt'?game.s.debt.from:game.s.turn;}
function render(){
 const s=game.s,p=game.current,a=game.s.players[actor()];$('round').textContent=started?`ROUND ${s.round}`:'2–4 PLAYERS';const dice=s.dice.map(d=>`<span class="die" aria-label="Dice ${d}">${['','⚀','⚁','⚂','⚃','⚄','⚅'][d]}</span>`).join('');
 let heading=started?`${esc(p.name)}’s turn`:'Your city awaits.',sub=started?`At ${esc(BOARD[p.pos].name)}`:'Gather your friends. Build your own story.',button='',note='';
 if(!started){button='<button class="primary" id="start-table">Set up your table &nbsp; →</button>';}
 else if(s.phase==='roll'){
  sub=p.jailed?`In jail · ${p.jailTurns} of 3 attempts used`:s.extra?'Doubles! Roll again.':sub;
  button='<button class="primary" id="roll-dice">Roll the dice &nbsp; ↗</button>';
  if(p.jailed)button+=`<div class="button-row"><button class="secondary" id="pay-jail">Pay ${money(50)}</button>${p.cards.length?'<button class="secondary" id="use-jail-card">Use free card</button>':''}</div>`;
  note='Roll, explore, and make your next move.';
 }else if(s.phase==='end'){heading=`${esc(p.name)}, all done.`;button='<button class="primary" id="end-turn">Pass the dice &nbsp; →</button>';note=`Next up: ${esc(nextName())}`;}
 else if(s.phase==='buy'){heading='A piece of Yerevan.';button='<button class="primary" id="open-action">View this property &nbsp; →</button>';note='Buy at the listed price, or start an auction.';}
 else if(s.phase==='buildingClaims'){heading='One building. More ambition.';sub='The bank’s final building is available.';button='<button class="primary" id="open-action">Resolve building claims &nbsp; →</button>';}
 else if(s.phase==='auction'){heading='Going once…';sub=`Auction · ${esc(BOARD[s.auction.i].name)}`;button='<button class="primary" id="open-action">Continue auction &nbsp; →</button>';}
 else if(s.phase==='card'){heading='The city has a surprise.';button='<button class="primary" id="open-action">Read your card &nbsp; →</button>';}
 else if(s.phase==='debt'){heading=`${esc(a.name)}, a little short.`;sub=`Payment due: ${money(s.debt.amount)}`;button='<button class="primary" id="open-action">Resolve payment &nbsp; →</button>';note='Sell buildings, mortgage deeds, or trade.';}
 else if(s.phase==='transfer'){heading='An inherited mortgage.';button='<button class="primary" id="open-action">Resolve transfer &nbsp; →</button>';}
 else if(s.phase==='won'){heading='The city has a winner.';button='<button class="primary" id="open-action">Celebrate &nbsp; ✦</button>';}
 $('turn-panel').innerHTML=`<div class="turn-card"><span class="eyebrow">${started?'YOUR NEXT MOVE':'WELCOME TO YEREVAN'}</span><h2>${heading}</h2><p>${sub}</p><div class="dice-row">${dice}<span class="dice-note">${p.jailed?'IN JAIL':s.extra?'DOUBLES':started?`TURN ${s.turn+1} · ${TOKENS[p.id].name.toUpperCase()}`:'A CITY WORTH<br>PLAYING FOR'}</span></div>${button}${note?`<div class="turn-sub">${note}</div>`:''}</div>`;
 $('roster').innerHTML=s.players.map(pl=>{const deeds=s.props.map((q,i)=>q.owner===pl.id?i:-1).filter(i=>i>=0);return `<div class="player-row ${started&&pl.id===s.turn?'active':''} ${pl.out?'out':''}" tabindex="0" role="button" data-player="${pl.id}" aria-label="${esc(pl.name)} properties"><span class="token" style="--c:${TOKENS[pl.id].color}">${TOKENS[pl.id].icon}</span><div class="player-info"><strong>${esc(pl.name)} ${started&&pl.id===s.turn?'<span style="color:#9aaa86;font-size:9px">●</span>':''}</strong><small>${pl.out?'BANKRUPT':`${TOKENS[pl.id].name}${pl.jailed?' · In jail':''}`}</small><div class="tiny-deeds">${deeds.map(i=>`<i style="background:${color(i)};opacity:${s.props[i].mortgaged?.35:1}"></i>`).join('')}</div></div><div class="player-money">${money(pl.cash)}<small>${deeds.length} DEED${deeds.length===1?'':'S'}${pl.cards.length?` · ${pl.cards.length} FREE CARD${pl.cards.length===1?'':'S'}`:''}</small></div></div>`;}).join('');
 $('roster').querySelectorAll('[data-player]').forEach(el=>{el.onclick=()=>started?showProperties(+el.dataset.player):showSetup();el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});
 $('journal').innerHTML=s.log.map(l=>`<p>${esc(l)}</p>`).join('');const stock=game.stock();$('bank-stock').textContent=`${stock.houses} houses · ${stock.hotels} hotels`;
 $('manage-btn').disabled=!started||s.phase==='won';$('trade-btn').disabled=!started||!game.canManage(actor());
 on('start-table',showSetup);on('open-action',showPhase);on('roll-dice',()=>{if(busy)return;busy=true;$('roll-dice').disabled=true;view?.roll();setTimeout(()=>{perform(()=>game.roll());busy=false;},850);});on('end-turn',()=>perform(()=>game.endTurn()));on('pay-jail',()=>perform(()=>game.jailPay()));on('use-jail-card',()=>perform(()=>game.jailCard()));view?.sync(game);
}
function nextName(){let n=game.s.turn;do{n=(n+1)%game.s.players.length;}while(game.s.players[n].out);return game.s.players[n].name;}
function showSetup(count=2,names=[]){
 if(typeof count!=='number')count=2;
 modal(`<span class="eyebrow">ԲԱՐԻ ԳԱԼՈՒՍՏ · WELCOME</span><h2>A game night in Yerevan.</h2><p>Buy the streets you love. Trade for the landmarks you want. Build your way from Kond to Republic Square.</p><div class="setup-hero"><span>✦</span><div><strong>One city. A whole evening.</strong><p>2–4 local players · Classic rules · Three.js 3D board</p></div></div><label>How many at the table?</label><div class="count-picker">${[2,3,4].map(n=>`<button id="count-${n}" class="${n===count?'active':''}">${n} players</button>`).join('')}</div><div id="name-fields">${Array.from({length:count},(_,i)=>`<div class="player-input"><span class="token" style="--c:${TOKENS[i].color}">${TOKENS[i].icon}</span><input id="name-${i}" aria-label="Player ${i+1} name" maxlength="22" value="${esc(names[i]||`Player ${i+1}`)}" placeholder="Player ${i+1}"><small style="min-width:78px;color:#87937c;font-size:9px">${TOKENS[i].name}</small></div>`).join('')}</div><button class="primary dark" id="begin-game">Let’s play · Արի խաղանք &nbsp; →</button>${saved&&!started?'<button class="secondary" id="resume-game" style="width:100%;margin-top:9px">Resume your saved game</button>':''}<p class="setup-foot">Each player starts with ${money(1500)}. Highest opening roll goes first.<br>Progress saves automatically in this browser.</p>`, 'setup',false,started);
 [2,3,4].forEach(n=>on(`count-${n}`,()=>showSetup(n,Array.from({length:count},(_,i)=>$(`name-${i}`).value))));
 on('begin-game',()=>{const ns=Array.from({length:count},(_,i)=>$(`name-${i}`).value.trim()||`Player ${i+1}`);game=new Game(ns);started=true;$('overlay').hidden=true;save();render();toast(`${game.current.name} won the opening roll and starts.`);});
 on('resume-game',()=>{game=new Game([],Math.random,saved);started=true;$('overlay').hidden=true;render();showPhase();});
}
function showPhase(){
 if(!started)return;
 const s=game.s;if(s.phase==='buy')showDeed(game.current.pos,true);else if(s.phase==='card')showCard();else if(s.phase==='auction')showAuction();else if(s.phase==='buildingClaims')showBuildingClaims();else if(s.phase==='debt')showDebt();else if(s.phase==='transfer')showTransfer();else if(s.phase==='won')showWinner();else{$('overlay').hidden=true;modalKind='';}
}
function showDeed(i,buy=false,backId=null){
 const b=BOARD[i],p=game.s.props[i],owner=p.owner===null?null:game.s.players[p.owner];
 if(!b.price){modal(`<span class="eyebrow">SPACE ${i+1} · YEREVAN</span><h2 id="modal-title">${esc(b.name)}</h2><p>${esc(b.fact)}</p><button class="primary dark" id="deed-close">Back to the table</button>`,'space');on('deed-close',closeModal);return;}
 const managed=owner&&game.canManage(owner.id);let rows='';
 if(b.type==='property')rows=[['Base rent',b.rents[0]],['Full color set · no buildings',b.rents[0]*2],['With 1 house',b.rents[1]],['With 2 houses',b.rents[2]],['With 3 houses',b.rents[3]],['With 4 houses',b.rents[4]],['With a hotel',b.rents[5]]].map(([label,val],n)=>`<tr class="${n===(p.houses?p.houses+1:game.ownsGroup(i,p.owner)?1:0)?'current':''}"><td>${label}</td><td>${money(val)}</td></tr>`).join('');
 else if(b.type==='station')rows=[1,2,3,4].map((n,j)=>`<tr><td>${n} metro deed${n>1?'s':''} owned</td><td>${money(25*2**j)}</td></tr>`).join('');
 else rows='<tr><td>One utility owned</td><td>4 × dice × ֏1,000</td></tr><tr><td>Both utilities owned</td><td>10 × dice × ֏1,000</td></tr>';
 let buttons='';if(buy){buttons=`<button class="primary dark" id="buy-deed" ${game.current.cash<b.price?'disabled':''}>Buy for ${money(b.price)}</button><div class="button-row"><button class="secondary" id="auction-deed">Decline & auction</button><button class="secondary" id="raise-cash">Manage assets</button></div>`;}
 else if(managed){buttons=`<div class="button-row">${b.type==='property'?`<button class="secondary" id="build">Build ${p.houses===4?'hotel':'house'}</button><button class="secondary" id="sell-building">Sell building</button>`:''}<button class="secondary" id="mortgage">${p.mortgaged?'Redeem':'Mortgage'}</button></div>${b.type==='property'&&game.group(i).some(j=>game.s.props[j].houses)?'<button class="text-button" id="liquidate-set" style="width:100%;margin-top:8px">Liquidate all buildings in this set at half price</button>':''}`;}
 modal(`<div class="deed-banner" style="--c:${color(i)}"><small>${b.type==='property'?esc(GROUPS[b.group].name.toUpperCase()):b.type==='station'?'YEREVAN METRO · TRANSPORT DEED':'CITY UTILITIES'}</small><h2 id="modal-title">${esc(b.name)}</h2></div><p>${esc(b.fact)}</p><div class="deed-price"><div><small>DEED VALUE</small><br><strong>${money(b.price)}</strong></div><div style="text-align:right"><span class="live-label">${p.mortgaged?'MORTGAGED':owner?`OWNED BY ${esc(owner.name).toUpperCase()}`:'AVAILABLE'}</span>${b.type==='property'?`<p style="margin:7px 0 0">${p.houses===5?'1 hotel':`${p.houses} houses`}</p>`:''}</div></div><table class="rent-table">${rows}</table><div class="deed-detail"><span>Mortgage: ${money(b.price/2)}<br>Redeem: ${money(Math.ceil(b.price*55/100))}</span><span>${b.type==='property'?`House / hotel: ${money(GROUPS[b.group].house)}<br>Sell buildings for half price`:'Mortgaged deeds collect no rent.'}</span></div>${buttons}<button class="text-button" id="back-assets" style="width:100%;margin-top:15px">${backId!==null?'← Back to properties':'Back to the table'}</button>`, 'deed',false,!buy);
 on('buy-deed',()=>perform(()=>game.buy()));on('auction-deed',()=>perform(()=>game.beginAuction()));on('raise-cash',()=>showProperties(game.current.id));on('back-assets',()=>backId!==null?showProperties(backId):closeModal());
 const manage=action=>perform(()=>game.manage(i,action,owner.id),()=>showDeed(i,false,owner.id));on('build',()=>perform(()=>game.requestBuilding(i,owner.id),()=>game.s.phase==='buildingClaims'?showBuildingClaims():showDeed(i,false,owner.id)));on('sell-building',()=>manage('sell'));on('mortgage',()=>manage(p.mortgaged?'redeem':'mortgage'));on('liquidate-set',()=>{modal(`<span class="eyebrow">SELL BUILDINGS</span><h2 id="modal-title">Liquidate ${esc(GROUPS[b.group].name)}?</h2><p>Return every house and hotel in this color set to the bank for half its purchase price. The deeds remain yours. This also works when there are not enough houses to break down a hotel.</p><button class="primary dark" id="confirm-liquidate">Sell all buildings in this set</button><button class="text-button" id="cancel-liquidate">Cancel</button>`,'confirm');on('confirm-liquidate',()=>manage('liquidate'));on('cancel-liquidate',()=>showDeed(i,false,owner.id));});
}
function showProperties(id=actor()){
 const player=game.s.players[id],deeds=game.s.props.map((p,i)=>p.owner===id?i:-1).filter(i=>i>=0);const manageable=game.canManage(id);
 modal(`<span class="eyebrow">YOUR CORNER OF YEREVAN</span><h2 id="modal-title">${esc(player.name)}’s properties</h2><p>Cash: <strong>${money(player.cash)}</strong> · ${deeds.length} deeds · ${player.cards.length} Get Out of Jail Free cards</p><p>${manageable?'Choose a deed to build, sell buildings, or manage a mortgage. Build and sell evenly across each color set.':'View the deeds below. Complete the pending card, auction or transfer before managing assets.'}</p><div class="property-list">${deeds.map(i=>`<button class="property-chip" style="--c:${color(i)}" data-deed="${i}"><strong>${esc(BOARD[i].name)}</strong><small>${game.s.props[i].mortgaged?'Mortgaged':game.s.props[i].houses===5?'Hotel':game.s.props[i].houses?`${game.s.props[i].houses} houses`:`Rent: ${BOARD[i].type==='utility'?'dice-based':money(game.rent(i))}`}</small></button>`).join('')}</div>${!deeds.length?'<p class="empty">Your city story starts with your first deed.</p>':''}<button class="primary dark" id="properties-done">Back to the table</button>`,'properties',true);
 $('modal').querySelectorAll('[data-deed]').forEach(el=>el.onclick=()=>showDeed(+el.dataset.deed,false,id));on('properties-done',closeModal);
}
function showCard(){const c=game.s.pendingCard,card=CARDS[c.deck][c.id];modal(`<span class="eyebrow">${c.deck==='chance'?'CHANCE · ՇԱՆՍ':'COMMUNITY CHEST · ՀԱՄԱՅՆՔ'}</span><div class="card-art">${c.deck==='chance'?'?':'✦'}</div><h2 id="modal-title" style="text-align:center">${esc(card.title)}</h2><p style="text-align:center;font-size:15px">${esc(card.text)}</p><p style="text-align:center">For ${esc(game.current.name)}</p><button class="primary dark" id="resolve-card">Continue &nbsp; →</button>`,'card',false,false);on('resolve-card',()=>perform(()=>game.continueCard()));}
function showAuction(){const a=game.s.auction,b=BOARD[a.i],p=game.s.players[a.bidder];modal(`<span class="eyebrow">THE CITY AUCTION HOUSE</span><h2 id="modal-title">${a.kind?`The bank’s last ${a.kind}`:esc(b.name)}</h2><p>${a.kind?`Only eligible claimants may bid. The winner places the ${a.kind} on their selected deed.`:`Everyone may bid, including the player who declined this deed.`} A pass withdraws that player from this auction.</p><div class="auction-meter"><small>CURRENT BID</small><strong>${money(a.bid)}</strong><small>${a.leader===null?'No bids yet':`Held by ${esc(game.s.players[a.leader].name)}`}</small></div><label for="bid-amount">${esc(p.name)}, your bid · cash ${money(p.cash)}</label><input id="bid-amount" type="number" min="${a.bid+1}" step="1" value="${a.bid+1}" aria-describedby="bid-help"><p id="bid-help" style="font-size:10px">Enter thousands of dram. For example, 25 means ֏25,000.</p><div class="button-row"><button class="primary dark" id="place-bid" style="margin:0">Place bid</button><button class="secondary" id="pass-bid">Pass</button></div><p>Still bidding: ${game.s.players.filter(p=>!p.out&&!a.passed.includes(p.id)&&(!a.placements||a.placements.some(e=>e.id===p.id))).map(p=>esc(p.name)).join(' · ')}</p>`,'auction',false,false);on('place-bid',()=>perform(()=>game.bid(Number($('bid-amount').value))));on('pass-bid',()=>perform(()=>game.pass()));}
function showBuildingClaims(){const r=game.s.buildRequest;modal(`<span class="eyebrow">A BUILDING SHORTAGE</span><h2 id="modal-title">The last ${r.kind} in the bank.</h2><p>Each eligible player may claim this building. If more than one player wants it, it goes to auction. Choose a legal placement, or leave “No claim”.</p>${r.candidates.map(c=>`<label for="claim-${c.id}">${esc(game.s.players[c.id].name)}</label><select id="claim-${c.id}"><option value="">No claim</option>${c.deeds.map(i=>`<option value="${i}" ${c.id===r.requester&&i===r.requested?'selected':''}>${esc(BOARD[i].name)} · ${money(GROUPS[BOARD[i].group].house)}</option>`).join('')}</select>`).join('')}<button class="primary dark" id="resolve-claims">Resolve claims &nbsp; →</button>`,'building-claims',false,false);on('resolve-claims',()=>{const claims={};r.candidates.forEach(c=>{const v=$(`claim-${c.id}`).value;if(v!=='')claims[c.id]=+v;});perform(()=>game.buildingClaims(claims));});}
function showDebt(){const d=game.s.debt,p=game.s.players[d.from];modal(`<span class="eyebrow">TIME TO BALANCE THE BOOKS</span><h2 id="modal-title">${esc(p.name)}, payment is due.</h2><p>${esc(d.reason||'Payment')} · Owed to ${d.to===null?'the bank':esc(game.s.players[d.to].name)}</p><div class="auction-meter"><small>AMOUNT DUE</small><strong>${money(d.amount)}</strong><small>Cash available: ${money(p.cash)} · Shortfall: ${money(Math.max(0,d.amount-p.cash))}</small></div><p>Raise cash by selling buildings, mortgaging deeds, or making a trade. Bankruptcy is allowed only if your cash and the liquidation value of all your assets cannot cover the debt.</p><div class="button-row"><button class="secondary" id="debt-assets">Manage properties</button><button class="secondary" id="debt-trade">Make a trade</button></div><button class="primary dark" id="settle-debt" ${p.cash<d.amount?'disabled':''}>Pay ${money(d.amount)}</button><button class="text-button danger" id="bankrupt" style="width:100%;margin-top:12px">Declare bankruptcy</button>`,'debt',false,false);on('debt-assets',()=>showProperties(p.id));on('debt-trade',()=>showTrade(p.id));on('settle-debt',()=>perform(()=>game.settleDebt()));on('bankrupt',()=>{modal(`<span class="eyebrow">LEAVE THE GAME</span><h2 id="modal-title">Declare ${esc(p.name)} bankrupt?</h2><p>Your remaining cash, deeds and cards will be handled by the bankruptcy rules. You will be out of this game.</p><button class="primary dark" id="confirm-bankrupt">Confirm bankruptcy</button><button class="text-button" id="cancel-bankrupt">Return to payment</button>`,'confirm',false,false);on('confirm-bankrupt',()=>perform(()=>game.bankrupt()));on('cancel-bankrupt',showDebt);});}
function showTransfer(){const t=game.s.transfer,b=BOARD[t.i],p=game.s.players[t.owner];modal(`<span class="eyebrow">INHERITED MORTGAGE</span><h2 id="modal-title">${esc(b.name)}</h2><p>${esc(p.name)}, this inherited deed is mortgaged. Pay the immediate 10% interest to keep the mortgage, or pay the mortgage plus interest to redeem it now.</p><button class="primary dark" id="transfer-keep">Keep mortgaged · ${money(Math.ceil(b.price*.05))}</button><button class="secondary" id="transfer-redeem" style="width:100%;margin-top:9px">Redeem now · ${money(Math.ceil(b.price*55/100))}</button>`,'transfer',false,false);on('transfer-keep',()=>perform(()=>game.transferMortgage(false)));on('transfer-redeem',()=>perform(()=>game.transferMortgage(true)));}
function showTrade(id=actor(),partner=null,draft=null){
 const others=game.s.players.filter(p=>!p.out&&p.id!==id);partner=partner??others[0]?.id;if(partner===undefined)return;const a=game.s.players[id],b=game.s.players[partner];
 const column=(pl,side)=>{const ids=game.s.props.map((p,i)=>p.owner===pl.id?i:-1).filter(i=>i>=0);return `<div class="trade-col"><strong>${esc(pl.name)} gives</strong><p>Cash: ${money(pl.cash)}</p>${ids.map(i=>{const locked=BOARD[i].type==='property'&&game.group(i).some(j=>game.s.props[j].houses);return `<label class="trade-deed"><input type="checkbox" name="${side}" value="${i}" ${(draft?.[side]||[]).includes(i)?'checked':''} ${locked?'disabled':''}><i style="--c:${color(i)}"></i><span>${esc(BOARD[i].name)}${locked?' · sell set’s buildings first':game.s.props[i].mortgaged?' · mortgaged':''}</span></label>${game.s.props[i].mortgaged?`<select id="mortgage-${i}" aria-label="Mortgage choice for ${esc(BOARD[i].name)}" style="font-size:10px;padding:8px;margin-bottom:9px"><option value="keep">Recipient keeps mortgage · ${money(Math.ceil(BOARD[i].price*5/100))}</option><option value="redeem" ${(draft?.redeem||[]).includes(i)?'selected':''}>Recipient redeems now · ${money(Math.ceil(BOARD[i].price*55/100))}</option></select>`:''}`;}).join('')||'<p>No deeds yet.</p>'}<label for="cash-${side}">Cash in thousands of dram</label><input type="number" min="0" step="1" id="cash-${side}" value="${draft?.[`cash${side}`]||0}"><label for="cards-${side}">Get Out of Jail Free cards</label><input type="number" min="0" max="${pl.cards.length}" id="cards-${side}" value="${draft?.[`cards${side}`]||0}"></div>`;};
 modal(`<span class="eyebrow">A GOOD DEAL GOES BOTH WAYS</span><h2 id="modal-title">Make a trade.</h2><label for="trade-partner">${esc(a.name)} is trading with</label><select id="trade-partner">${others.map(p=>`<option value="${p.id}" ${p.id===partner?'selected':''}>${esc(p.name)}</option>`).join('')}</select><p>Deeds, cash and jail cards can be exchanged. For each mortgaged deed, the recipient can redeem it now or pay 10% interest to keep the mortgage. Redeeming later costs the mortgage plus another 10%.</p><div class="trade-grid">${column(a,'A')}${column(b,'B')}</div><button class="primary dark" id="review-trade">Review proposal &nbsp; →</button><button class="text-button" id="cancel-trade">Cancel</button>`,'trade',true);
 on('trade-partner',()=>showTrade(id,Number($('trade-partner').value)));on('cancel-trade',closeModal);
 on('review-trade',()=>{const d={a:id,b:partner,A:[...$('modal').querySelectorAll('input[name="A"]:checked')].map(e=>+e.value),B:[...$('modal').querySelectorAll('input[name="B"]:checked')].map(e=>+e.value),cashA:Number($('cash-A').value),cashB:Number($('cash-B').value),cardsA:Number($('cards-A').value),cardsB:Number($('cards-B').value),redeem:[...$('modal').querySelectorAll('select[id^="mortgage-"]')].filter(e=>e.value==='redeem'&&$('modal').querySelector(`input[type="checkbox"][value="${e.id.slice(9)}"]`)?.checked).map(e=>+e.id.slice(9))};tradeDraft=d;
  const summary=(pl,side)=>`<p><strong>${esc(pl.name)} gives:</strong><br>${d[side].map(i=>esc(BOARD[i].name)).join(', ')||'No deeds'} · ${money(d[`cash${side}`])} · ${d[`cards${side}`]} free jail cards</p>`;
  modal(`<span class="eyebrow">REVIEW TOGETHER</span><h2 id="modal-title">A deal for ${esc(a.name)} & ${esc(b.name)}.</h2><div class="trade-review">${summary(a,'A')}${summary(b,'B')}</div><p>Pass the screen to ${esc(b.name)}. Accept only when both players agree. ${d.redeem.length?`Redeem immediately: ${d.redeem.map(i=>esc(BOARD[i].name)).join(', ')}. `:''}Any mortgage interest or redemption costs are paid by the receiving players.</p><button class="primary dark" id="accept-trade">${esc(b.name)}: accept this trade</button><div class="button-row"><button class="secondary" id="edit-trade">Edit proposal</button><button class="secondary" id="reject-trade">Decline</button></div>`,'trade-review');
  on('accept-trade',()=>perform(()=>{game.trade(d.a,d.b,d.A,d.B,d.cashA,d.cashB,d.cardsA,d.cardsB,d.redeem);tradeDraft=null;toast('Trade complete.');}));on('edit-trade',()=>showTrade(id,partner,d));on('reject-trade',closeModal);
 });
}
function showWinner(){const p=game.s.players.find(p=>!p.out);modal(`<span class="eyebrow">THE PINK CITY HAS A NEW TYCOON</span><div class="winner">✦</div><h2 id="modal-title" style="text-align:center">${esc(p.name)} owns the night.</h2><p style="text-align:center">The last player standing wins.<br>${game.s.round} rounds · ${money(p.cash)} cash · ${game.s.props.filter(x=>x.owner===p.id).length} deeds</p><button class="primary dark" id="play-again">Another night in Yerevan</button><button class="secondary" id="winner-menu" style="width:100%;margin-top:10px">Export save / game menu</button>`,'winner',false,false);on('play-again',()=>showSetup(game.s.players.length,game.s.players.map(p=>p.name)));on('winner-menu',showMenu);}
function showRules(){modal(`<span class="eyebrow">THE TABLE’S HANDBOOK</span><h2 id="modal-title">Classic rules. A Yerevan soul.</h2><p>Modern classic rules with fixed income tax. All prices and rents use the classic board’s balance, multiplied by 1,000 and displayed as Armenian dram. The landmarks, metro deeds and stories are a local theme; this is an unofficial fan-made edition.</p><div class="rules">
 <details open><summary>01 · Set up & win</summary><p>2–4 people play in turn on one computer. Each starts with ${money(1500)}. Opening rolls select the first player; play proceeds in seat order. Be the last player left after everyone else goes bankrupt. There is no turn limit. Use the 3D / Top view buttons and zoom controls; click any space for its deed.</p></details>
 <details><summary>02 · Turns, START & doubles</summary><p>Roll two dice, move clockwise and resolve the space. Passing or landing on START earns ${money(200)}. Doubles give another roll after you resolve the space. Three consecutive doubles send you directly to jail. Passing the dice ends your turn. The bank handles all cash automatically and has unlimited money.</p></details>
 <details><summary>03 · Buying & auctions</summary><p>Buy an unowned deed at its printed price, or decline and auction it. All active players may bid, including the player who declined. Bids use available cash and must increase by at least ${money(1)}. In this computer auction, pressing Pass withdraws from that auction. The last bidder wins; if everyone passes without bidding, the bank keeps it. There are 22 streets, four metro deeds (the railroad rules), and two utilities.</p></details>
 <details><summary>04 · Rent, metro & utilities</summary><p>Rent is collected automatically on landing. Mortgaged deeds collect no rent. Owning an entire color set doubles its unimproved street rent, even if a sister deed is mortgaged. The four metro deeds charge ${money(25)}, ${money(50)}, ${money(100)} or ${money(200)} with one, two, three or four owned. A utility costs 4× the dice total with one owned, or 10× with both. Special Chance cards apply their stated metro / utility rent. Players in jail still collect rent.</p></details>
 <details><summary>05 · Houses, hotels & the bank supply</summary><p>Own all deeds in a color set and clear all its mortgages to build. Use My properties or click a player. Build evenly: no deed may be more than one level ahead of its set. Four houses may be exchanged for one hotel by paying one additional building cost. The bank has 32 houses and 12 hotels; you cannot buy unavailable stock. Buildings sell back at half price, evenly. A hotel sells back into four houses if stock allows; “Liquidate set” returns every building in the whole set for half price when you need to sell the set together. If multiple players want the bank’s last house or hotel, eligible players choose placements and auction it. Building is available between resolved actions, including other players’ turns through their property panels.</p></details>
 <details><summary>06 · Mortgages & trading</summary><p>Sell all buildings in the color set before mortgaging or trading a street. Mortgage a deed for half its purchase price; redeem at the mortgage amount plus 10%, rounded up to the next game unit. Exchange deeds, cash or Get Out of Jail Free cards via Make a trade, then have the other player accept. The recipient of a mortgaged deed chooses between redeeming immediately at mortgage + 10%, or keeping the mortgage and paying 10% interest immediately. Keeping that mortgage requires paying another 10% when redeeming later. No player loans, IOUs or rent immunity deals are allowed.</p></details>
 <details><summary>07 · Jail & leaving jail</summary><p>Go to Jail, a jail card, or a third consecutive double sends you straight to jail without a START salary and ends your turn. On each of your next three turns, try to roll doubles. Doubles release you and move you by that roll, with no extra roll. Before rolling you may instead pay ${money(50)} or use a free jail card. On a third failed roll you must pay ${money(50)}, leave, and move by the dice. If you cannot pay, resolve the debt first. Landing on the jail space normally is just visiting.</p></details>
 <details><summary>08 · Chance, Chest, taxes & parking</summary><p>Each shuffled deck has 16 cards. Resolve a drawn card and put it at the bottom; free jail cards are held until used or traded. Card movement can trigger another card or a property action. Repairs count each hotel as one hotel, not four houses. Income tax is ${money(200)}; luxury tax is ${money(100)}. Free Parking gives no money or jackpot. Money paid to the bank stays in the bank.</p></details>
 <details><summary>09 · Debt & bankruptcy</summary><p>A payment pauses play if cash is short. The debtor may sell buildings, mortgage deeds and negotiate trades. If liquidation can pay the debt, raise the money and pay it. If it cannot, declare bankruptcy. When owing a player, sell buildings back at half price and transfer cash, deeds and free jail cards to that player; inherited mortgages require an immediate interest or redemption choice. When owing the bank, return jail cards, cancel mortgages and auction the deeds. Eliminated players leave the game; the last remaining player wins.</p></details>
 <details><summary>10 · Saving & the local edition</summary><p>The game saves after actions in this browser. Use the menu to export or import a JSON save. A new game replaces the browser save only after you start it. This is a local pass-and-play game without online accounts or computer opponents. The landmarks are theme choices, not actual properties for sale or a travel map.</p></details>
 </div><p style="font-size:10px">Rules reference: <a href="https://instructions.hasbro.com/en-us/instruction/monopoly-board-game-classic-game-with-storage-tray-and-larger-tokens-family-games-8" target="_blank" rel="noopener">Hasbro’s classic game instructions ↗</a></p><button class="primary dark" id="rules-done">Back to the table</button>`,'rules',true);on('rules-done',()=>started?closeModal():showSetup());}
function showMenu(){modal(`<span class="eyebrow">YOUR GAME NIGHT</span><h2 id="modal-title">Take your time.</h2><p>Games save automatically on this browser. Export a save to keep a copy or continue on another computer.</p>${started?'<button class="primary dark" id="export-save">Export game save</button>':''}<button class="secondary" id="import-save" style="width:100%;margin-top:10px">Import game save</button><input type="file" accept=".json,application/json" id="save-file" hidden><button class="secondary" id="menu-rules" style="width:100%;margin-top:10px">Read the rules</button><button class="secondary" id="new-game" style="width:100%;margin-top:10px">Set up a new game</button><button class="text-button" id="menu-close" style="width:100%;margin-top:12px">Back to the table</button>`,'menu');
 on('export-save',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(game.s,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='yerevan-monopoly-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported.');});
 on('import-save',()=>$('save-file').click());$('save-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('Save file is too large.');const s=JSON.parse(await f.text());validateSave(s);game=new Game([],Math.random,s);started=true;save();render();showPhase();toast('Game restored.');}catch(err){toast(`Could not import: ${err.message}`);}};
 on('new-game',()=>{if(!started){showSetup();return;}modal(`<span class="eyebrow">A FRESH START</span><h2 id="modal-title">Start another game?</h2><p>Your current browser save will be replaced when the new game begins. Export it first if you want to keep it.</p><button class="primary dark" id="confirm-new">Set up new table</button><button class="text-button" id="cancel-new">Return to current game</button>`,'confirm');on('confirm-new',()=>showSetup(game.s.players.length,game.s.players.map(p=>p.name)));on('cancel-new',closeModal);});on('menu-rules',showRules);on('menu-close',()=>started?closeModal():showSetup());
}
function validateSave(s){if(s?.version!==1||!Array.isArray(s.players)||s.players.length<2||s.players.length>4||!Array.isArray(s.props)||s.props.length!==40||!Number.isInteger(s.turn)||s.turn<0||s.turn>=s.players.length||!['roll','end','buy','auction','buildingClaims','card','debt','transfer','won'].includes(s.phase)||!Array.isArray(s.queue)||!s.decks||!Array.isArray(s.log))throw Error('This is not a valid Yerevan Monopoly save.');for(const [i,p] of s.players.entries())if(p.id!==i||typeof p.name!=='string'||!Number.isFinite(p.cash)||p.cash<0||!Number.isInteger(p.pos)||p.pos<0||p.pos>39||!Array.isArray(p.cards))throw Error('Invalid player data.');for(const p of s.props)if(!(p.owner===null||Number.isInteger(p.owner)&&p.owner>=0&&p.owner<s.players.length)||!Number.isInteger(p.houses)||p.houses<0||p.houses>5)throw Error('Invalid property data.');for(const d of ['chance','chest'])if(!Array.isArray(s.decks[d])||s.decks[d].some(i=>!Number.isInteger(i)||i<0||i>15))throw Error('Invalid card deck.');if(s.phase==='auction'&&!s.auction||s.phase==='debt'&&!s.debt||s.phase==='card'&&!s.pendingCard||s.phase==='transfer'&&!s.transfer)throw Error('Missing action data.');}
on('rules-btn',showRules);on('settings-btn',showMenu);on('manage-btn',()=>showProperties());on('trade-btn',()=>showTrade());on('tab-players',()=>{$('roster').hidden=false;$('roster').style.display='';$('journal').hidden=true;$('tab-players').classList.add('active');$('tab-log').classList.remove('active');});on('tab-log',()=>{$('roster').hidden=true;$('roster').style.display='none';$('journal').hidden=false;$('tab-log').classList.add('active');$('tab-players').classList.remove('active');});
on('view-3d',()=>{view?.setView('3d');$('view-3d').classList.add('active');$('view-top').classList.remove('active');});on('view-top',()=>{view?.setView('top');$('view-top').classList.add('active');$('view-3d').classList.remove('active');});on('zoom-out',()=>view?.setZoom(-.1));on('zoom-in',()=>view?.setZoom(.1));on('reset-view',()=>{if(view){view.zoom=1;const mode=$('view-3d').disabled?'top':'3d';view.setView(mode);$('view-3d').classList.toggle('active',mode==='3d');$('view-top').classList.toggle('active',mode==='top');}});
$('overlay').addEventListener('click',e=>{if(e.target===$('overlay')&&$('close-modal'))closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('close-modal'))closeModal();if(e.key==='Tab'&&!$('overlay').hidden){const els=[...$('modal').querySelectorAll('button:not(:disabled),input:not([hidden]):not(:disabled),select,summary,a')].filter(el=>el.offsetParent!==null);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
const selectSpace=i=>showDeed(i,started&&game.s.phase==='buy'&&game.current.pos===i);
try{view=new BoardView($('scene'),selectSpace);}catch(e){view=new CanvasBoardView($('scene'),selectSpace);$('view-3d').classList.remove('active');$('view-3d').disabled=true;$('view-3d').title='WebGL is unavailable in this browser';$('view-top').classList.add('active');console.info('Using the canvas top-view fallback because WebGL is unavailable.');}
render();showSetup();
